// Main computational kernel. The whole function will be timed.
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(auto path_ij) {
	// Base view: path_ij has dimensions (i, j)
	// For floyd-warshall we also need views:
	//   path_ik ~ path[i][k]  => dims (i, k)
	//   path_kj ~ path[k][j]  => dims (k, j)
	using namespace noarr;

	auto path_ik = path_ij ^ noarr::rename<'j', 'k'>(); // j -> k, dims (i, k)
	auto path_kj = path_ij ^ noarr::rename<'i', 'k'>(); // i -> k, dims (k, j)

#pragma scop
	// Outer loop over k
	traverser(path_ij, path_ik, path_kj).template for_dims<'k'>([=](auto trav_k) {
		// Inner loops over i, j (order chosen by traverser, but for fixed k)
		trav_k.for_each([=](auto state) {
			// state contains 'i', 'j', and 'k'
			auto via_k = path_ik[state] + path_kj[state];
			auto &current = path_ij[state];

			current = current < via_k ? current : via_k;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Set lengths for logical dimensions
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// Allocate data
	auto path = noarr::bag(noarr::scalar<num_t>() ^ tuning.path_layout ^ set_lengths);

	// Initialize data
	init_array(path.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_floyd_warshall(path.get_ref());

